      function fillUserUsageSubscriptionOptions(){var select=document.getElementById('userUsageSubscriptionFilter');if(!select)return;var selected=select.value;select.innerHTML='<option value="">所有订阅</option>'+accounts.map(function(a){return '<option value="'+a.id+'">'+escapeHTML(a.name)+' · '+escapeHTML(a.provider)+'</option>'}).join('');if(selected&&Array.prototype.some.call(select.options,function(option){return option.value===selected}))select.value=selected;else select.value='';bindSelectControl(select)}
