      async function loadUsageBySubscription(){if(!isAdmin())return;subscriptionUsageResult={data:[],totals:{}};renderUsageBySubscription(subscriptionUsageResult);$('usageBySubscriptionTable').innerHTML='<div class="empty">正在加载用量…</div>';try{subscriptionUsageResult=await request('/api/usage/subscriptions?'+usageQuery(usageRange,'usageFrom','usageTo'));renderUsageBySubscription(subscriptionUsageResult);var totals=subscriptionUsageResult.totals||{};$('statRequests').textContent=formatNumber(totals.requests);$('statInput').textContent=formatNumber(totals.input_tokens);$('statOutput').textContent=formatNumber(totals.output_tokens)}catch(e){$('usageBySubscriptionTable').innerHTML='<div class="empty">用量加载失败：'+escapeHTML(e.message)+'</div>';$('usageRangeTotals').textContent='加载失败';toast(e.message,true)}}
