      function usageSortValue(row,table,key){var u=row.usage||{};if(key==='requests'||key==='input_tokens'||key==='output_tokens'||key==='cache_creation_tokens'||key==='cache_read_tokens'||key==='total_tokens')return Number(u[key])||0;if(key==='subscription')return String(row.subscription_name||('订阅 '+row.subscription_id));if(key==='provider')return String(row.provider||'');if(key==='user')return String(row.username||(row.user_id!=null?'用户 '+row.user_id:'未归属'));if(key==='role')return String(row.role||'');if(key==='enabled')return row.user_id==null?-1:(row.enabled?1:0);return ''}
      function sortUsageRows(rows,table,state){if(!state.key)return rows.slice();return rows.slice().sort(function(a,b){var av=usageSortValue(a,table,state.key);var bv=usageSortValue(b,table,state.key);var compared=typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv),'zh-CN',{numeric:true,sensitivity:'base'});if(!compared){var ai=table==='subscription'?(Number(a.subscription_id)||0):(a.user_id==null?Number.MAX_SAFE_INTEGER:Number(a.user_id));var bi=table==='subscription'?(Number(b.subscription_id)||0):(b.user_id==null?Number.MAX_SAFE_INTEGER:Number(b.user_id));compared=ai-bi}return compared*state.direction})}
