      function renderUsageBySubscription(result){subscriptionUsageResult=result||{data:[],totals:{}};var rows=sortUsageRows(subscriptionUsageResult.data||[],'subscription',subscriptionUsageSort);var totals=subscriptionUsageResult.totals||{};$('usageRangeTotals').textContent='请求 '+formatNumber(totals.requests||0)+' · 输入 '+formatNumber(totals.input_tokens||0)+' · 输出 '+formatNumber(totals.output_tokens||0)+' · 缓存创建 '+formatNumber(totals.cache_creation_tokens||0)+' · 缓存读取 '+formatNumber(totals.cache_read_tokens||0);if(!rows.length){$('usageBySubscriptionTable').innerHTML='<div class="empty">当前选择的时间范围暂无用量记录，请确认已接入订阅或选择其他时间范围。</div>';return}$('usageBySubscriptionTable').innerHTML='<table><thead><tr>'+usageSortHeader('subscription','subscription','订阅',subscriptionUsageSort)+usageSortHeader('subscription','provider','平台',subscriptionUsageSort)+usageSortHeader('subscription','requests','请求',subscriptionUsageSort)+usageSortHeader('subscription','input_tokens','输入',subscriptionUsageSort)+usageSortHeader('subscription','output_tokens','输出',subscriptionUsageSort)+usageSortHeader('subscription','cache_creation_tokens','缓存创建',subscriptionUsageSort)+usageSortHeader('subscription','cache_read_tokens','缓存读取',subscriptionUsageSort)+usageSortHeader('subscription','total_tokens','合计 Token',subscriptionUsageSort)+'</tr></thead><tbody>'+rows.map(function(row){var u=row.usage||{};return '<tr><td><div class="account-name">'+escapeHTML(row.subscription_name||('订阅 '+row.subscription_id))+'</div><div class="subtle">ID '+row.subscription_id+'</div></td><td>'+escapeHTML(row.provider||'')+'</td><td>'+formatNumber(u.requests||0)+'</td><td>'+formatNumber(u.input_tokens||0)+'</td><td>'+formatNumber(u.output_tokens||0)+'</td><td>'+formatNumber(u.cache_creation_tokens||0)+'</td><td>'+formatNumber(u.cache_read_tokens||0)+'</td><td>'+formatNumber(u.total_tokens||0)+'</td></tr>'}).join('')+'</tbody></table>'}
      function renderUsageByUser(result){userUsageResult=result||{data:[],totals:{}};var rows=sortUsageRows(userUsageResult.data||[],'user',userUsageSort);var totals=userUsageResult.totals||{};$('usageByUserTotals').textContent='请求 '+formatNumber(totals.requests||0)+' · 输入 '+formatNumber(totals.input_tokens||0)+' · 输出 '+formatNumber(totals.output_tokens||0)+' · 缓存创建 '+formatNumber(totals.cache_creation_tokens||0)+' · 缓存读取 '+formatNumber(totals.cache_read_tokens||0);if(!rows.length){$('usageByUserTable').innerHTML='<div class="empty">所选时间范围内暂无用户用量。</div>';$('usageByUserPager').innerHTML=pageSizeSelectHTML('userUsagePageSize',userUsageLimit);bindPageSizeSelect('userUsagePageSize');return}if(userUsageOffset>=rows.length)userUsageOffset=Math.max(0,rows.length-userUsageLimit);if(userUsageOffset<0)userUsageOffset=0;var pageRows=rows.slice(userUsageOffset,userUsageOffset+userUsageLimit);$('usageByUserTable').innerHTML='<table><thead><tr>'+usageSortHeader('user','user','用户',userUsageSort)+usageSortHeader('user','role','角色',userUsageSort)+usageSortHeader('user','enabled','状态',userUsageSort)+usageSortHeader('user','requests','请求',userUsageSort)+usageSortHeader('user','input_tokens','输入',userUsageSort)+usageSortHeader('user','output_tokens','输出',userUsageSort)+usageSortHeader('user','cache_creation_tokens','缓存创建',userUsageSort)+usageSortHeader('user','cache_read_tokens','缓存读取',userUsageSort)+usageSortHeader('user','total_tokens','合计 Token',userUsageSort)+'</tr></thead><tbody>'+pageRows.map(function(row){var u=row.usage||{};var assigned=row.user_id!=null;return '<tr><td><div class="account-name">'+escapeHTML(row.username||(assigned?'用户 '+row.user_id:'未归属'))+'</div>'+(assigned?'<div class="subtle">ID '+row.user_id+'</div>':'<div class="subtle">旧 Key 或无法识别的历史调用</div>')+'</td><td>'+escapeHTML(row.role==='admin'?'管理员':(row.role==='user'?'用户':'—'))+'</td><td>'+(assigned?'<span class="badge '+(row.enabled?'ok':'off')+'">'+(row.enabled?'已启用':'已停用')+'</span>':'—')+'</td><td>'+formatNumber(u.requests||0)+'</td><td>'+formatNumber(u.input_tokens||0)+'</td><td>'+formatNumber(u.output_tokens||0)+'</td><td>'+formatNumber(u.cache_creation_tokens||0)+'</td><td>'+formatNumber(u.cache_read_tokens||0)+'</td><td>'+formatNumber(u.total_tokens||0)+'</td></tr>'}).join('')+'</tbody></table>';var from=rows.length?userUsageOffset+1:0;var to=Math.min(userUsageOffset+pageRows.length,rows.length);$('usageByUserPager').innerHTML=pageSizeSelectHTML('userUsagePageSize',userUsageLimit)+'<span class="pager-summary">'+from+'-'+to+' / '+formatNumber(rows.length)+'</span><button class="btn" type="button" id="userUsagePrev"'+(userUsageOffset<=0?' disabled':'')+'>上一页</button><button class="btn" type="button" id="userUsageNext"'+(userUsageOffset+userUsageLimit>=rows.length?' disabled':'')+'>下一页</button>';bindPageSizeSelect('userUsagePageSize')}
      var renderUsageBySubscriptionBase=renderUsageBySubscription;renderUsageBySubscription=function(result){renderUsageBySubscriptionBase(result);if(!result||!(result.data||[]).length)$('usageBySubscriptionTable').innerHTML='<div class="empty">'+usageEmptyReason(result,'subscription')+'</div>'};var renderUsageByUserBase=renderUsageByUser;renderUsageByUser=function(result){renderUsageByUserBase(result);if(!result||!(result.data||[]).length)$('usageByUserTable').innerHTML='<div class="empty">'+usageEmptyReason(result,'user')+'</div>'}
      function setUsageRange(range){usageRange=range;['1d','1w','1m','custom'].forEach(function(name){var button=$('usageRange'+name.toUpperCase());if(button)button.classList.toggle('active',usageRange===name)});$('usageCustomFields').hidden=usageRange!=='custom';if(usageRange!=='custom')loadUsageBySubscription()}
