      function headerDiffText(original,outbound){var before=headerTextMap(original),after=headerTextMap(outbound),keys=Object.keys(before).concat(Object.keys(after).filter(function(key){return !Object.prototype.hasOwnProperty.call(before,key)}));return keys.map(function(key){var oldValue=before[key],newValue=after[key];if(oldValue===newValue)return'  '+key+': '+oldValue;if(oldValue==null)return'+ '+key+': '+newValue;if(newValue==null)return'- '+key+': '+oldValue;return'~ '+key+': '+oldValue+' → '+newValue}).join('\n')}
